package com.madhukar.upisplitter.controller;
import com.madhukar.upisplitter.dto.*; import com.madhukar.upisplitter.dto.ApiDtos.TransactionView; import com.madhukar.upisplitter.service.TransactionService; import org.springframework.security.core.Authentication; import com.madhukar.upisplitter.model.PaymentTransaction.Status; import com.madhukar.upisplitter.service.PaymentPlanService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/transactions") public class TransactionController {private final TransactionService service; private final PaymentPlanService plans;public TransactionController(TransactionService s,PaymentPlanService p){service=s;plans=p;}@GetMapping public ApiDtos.ApiResponse<List<TransactionView>> list(Authentication a){return ApiResponseFactory.ok("Transactions loaded",service.list((String)a.getDetails()));}@GetMapping("/{id}") public ApiDtos.ApiResponse<TransactionView> get(@PathVariable String id,Authentication a){var x=service.get((String)a.getDetails(),id);return ApiResponseFactory.ok("Transaction loaded",new TransactionView(x.getId(),x.getPaymentPlanId(),x.getAmount(),x.getStatus().name(),x.getCreatedAt(),x.getUpdatedAt(),x.getCompletedAt(),x.getSequence()));}@PatchMapping("/{id}/simulate-success") public ApiDtos.ApiResponse<com.madhukar.upisplitter.dto.PaymentDtos.StatusResponse> success(@PathVariable String id,Authentication a){return ApiResponseFactory.ok("Payment updated",plans.changeStatus((String)a.getDetails(),id,Status.SUCCESS));}@PatchMapping("/{id}/simulate-failure") public ApiDtos.ApiResponse<com.madhukar.upisplitter.dto.PaymentDtos.StatusResponse> failure(@PathVariable String id,Authentication a){return ApiResponseFactory.ok("Payment updated",plans.changeStatus((String)a.getDetails(),id,Status.FAILED));}}
